Section Segs.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma bb_A : forall fr cs regs m (s pixs : Z) (v : pixv) (ret : word),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> reg_get fr 10 = L10 -> reg_get fr 11 = L1 ->
    exists regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x2e9e4 : word) m rom)
                  (@mkst (mkFP (bvmap_set 9 L10 (bvmap_set 8 L1 fr)) cs) regs' (0x2ea10 : word) (FRB m s ret regs fr) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 8 = Z_to_bv 64 pixs /\ getr regs' 10 = Z_to_bv 64 (p_d v)
