  Lemma bb_B : forall (fx : FPState) regs m (s pixs : Z) (v : pixv),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (p_d v = 8 \/ p_d v = 32)%Z ->
    getr regs 8 = Z_to_bv 64 pixs -> getr regs 10 = Z_to_bv 64 (p_d v) ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2ea10 : word) m rom) (@mkst fx regs' (0x2ea28 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 (p_cmap v) /\ getr regs' 1 = Z_to_bv 64 0x2ea28
      /\ regs_agree (fun x => In x [1; 10; 11]%list) regs regs'.
