  Lemma bb_Nc : forall (fx : FPState) regs m (cm : Z),
    (1 <= cm < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 0x38470) 8 = Some (Z_to_le_bytes 8 0x394e0) -> rdn SEGS m (Z_to_bv 64 0x394e0) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 10 = Z_to_bv 64 cm ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2ea28 : word) m rom) (@mkst fx regs' (0x2eb60 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x115b8 /\ getr regs' 11 = Z_to_bv 64 0x11f94
      /\ regs_agree (fun x => In x [10; 11]%list) regs regs'.
