  (* [comment removed for export] *)
  Lemma bb_NT : forall fr0 fr cs regs r0 m (s msg : Z) (ret : word),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> cellsZ m (frameb s ret r0 fr0) ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 10 = Z_to_bv 64 msg -> getr regs 11 = Z_to_bv 64 0x11f94 ->
    exists regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x2eb60 : word) m rom)
                  (@mkst (mkFP (bvmap_set 9 (reg_get fr0 9) (bvmap_set 8 (reg_get fr0 8) fr)) cs) regs' (0x17c74 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 msg /\ getr regs' 11 = Z_to_bv 64 0x11f94 /\ getr regs' 12 = Z_to_bv 64 0
      /\ (forall x, In x [8; 9]%bv -> getr regs' x = getr r0 x)
