  (* [comment removed for export] *)
  Lemma bb_C : forall fr cs regs m,
    frm_zero cs -> reg_get fr 9 = L10 -> reg_get fr 8 = L1 -> getr regs 10 = Z_to_bv 64 0 ->
    exists fr' cs' regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x2ea28 : word) m rom) (@mkst (mkFP fr' cs') regs' (0x2d000 : word) m rom)
      /\ frm_zero cs' /\ reg_get fr' 10 = L10 /\ reg_get fr' 11 = L1 /\ reg_get fr' 8 = L1 /\ reg_get fr' 9 = L10
      /\ (forall r : reg, r <> 10%bv -> r <> 11%bv -> r <> 15%bv -> reg_get fr' r = reg_get fr r)
      /\ getr regs' 10 = Z_to_bv 64 20 /\ getr regs' 11 = Z_to_bv 64 20 /\ getr regs' 1 = Z_to_bv 64 0x2ead4
      /\ regs_agree (fun x => In x [1; 10; 11]%list) regs regs'.
Proof.
