  (* [comment removed for export] *)
  Lemma bb_D : forall fr cs regs m (s skel : Z),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 48)) 8 = true -> reg_get fr 8 = L1 ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 10 = Z_to_bv 64 skel ->
    exists regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x2ead4 : word) m rom)
                  (@mkst (mkFP (bvmap_set 10 L1 fr) cs) regs' (0x2eba0 : word) (wbytes m (Z_to_bv 64 (s - 48)) (w8 (Z_to_bv 64 skel))) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 9 = Z_to_bv 64 skel /\ getr regs' 1 = Z_to_bv 64 0x2eae4
      /\ regs_agree (fun x => In x [1; 9]%list) regs regs'.
Proof.
