  (* [comment removed for export] *)
  Lemma bb_E : forall (fx : FPState) regs m (s pixs skel rkel : Z),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 56)) 8 = true ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 10 = Z_to_bv 64 rkel -> getr regs 8 = Z_to_bv 64 pixs -> getr regs 9 = Z_to_bv 64 skel ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2eae4 : word) m rom) (@mkst fx regs' (0x2e358 : word) (wbytes m (Z_to_bv 64 (s - 56)) (w8 (Z_to_bv 64 rkel))) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 skel /\ getr regs' 12 = Z_to_bv 64 rkel
      /\ getr regs' 1 = Z_to_bv 64 0x2eaf8
      /\ regs_agree (fun x => In x [1; 10; 11; 12]%list) regs regs'.
Proof.
