  (* [comment removed for export] *)
  Lemma bb_F : forall (fx : FPState) regs m (s pixd : Z),
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 10 = Z_to_bv 64 pixd ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x2eaf8 : word) m rom) (@mkst fx regs' (0x2c820 : word) m rom)
      /\ getr regs' 8 = Z_to_bv 64 pixd /\ getr regs' 10 = Z_to_bv 64 (s - 48) /\ getr regs' 1 = Z_to_bv 64 0x2eb04
      /\ regs_agree (fun x => In x [1; 8; 10]%list) regs regs'.
Proof.
