  (* [comment removed for export] *)
  Lemma bb_H : forall fr0 fr cs regs r0 m (s pixd : Z) (ret : word),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret -> cellsZ m (frameb s ret r0 fr0) ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 8 = Z_to_bv 64 pixd ->
    exists regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x2eb0c : word) m rom) (@mkst (mkFP (bvmap_set 9 (reg_get fr0 9) (bvmap_set 8 (reg_get fr0 8) fr)) cs) regs' ret m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 pixd
      /\ (forall x, In x [8; 9]%bv -> getr regs' x = getr r0 x)
      /\ regs_agree (fun x => In x [1; 2; 8; 9; 10]%list) regs regs'.
Proof.
